using System.Collections.Generic;
namespace GreySeer
{
    internal static class StringsTable
    {
        internal static readonly Dictionary<string, (string ko, string en)> Table = new Dictionary<string, (string ko, string en)>
        {
            { "archetype.name", ("그레이 시어", "Grey Seer") },
            { "archetype.short", ("주문과 검격을 번갈아 맞혀 같은 적의 빈틈을 여는 아카니스트.", "An arcanist who alternates spells and strikes with a chosen melee weapon and a quarterstaff.") },
            { "archetype.desc", ("그레이 시어는 본편 아카니스트의 주문 성장을 따릅니다. 1·5·9·13·17레벨 익스플로잇을 교환하고, 1·7·13레벨에 쌍수 전투 계열 특기를 받습니다. 선택한 무기와 지팡이를 함께 들면 두 무기의 근접 명중이 향상됩니다.", "A grey seer retains arcanist spell progression and trades the exploits at levels 1, 5, 9, 13 and 17 for training with a chosen melee weapon and a quarterstaff, gaining the two-weapon fighting feats at levels 1, 7 and 13.") },
            { "choice.name", ("검격 무기 선택", "Spellstrike Weapon Choice") },
            { "choice.desc", ("지팡이와 함께 사용할 한손 근접 무기 종류 하나를 고르고 그 무기에 숙련됩니다. 선택한 종류의 무기를 어느 손에 들든 반대 손에 쿼터스태프를 들면 두 무기 모두 명중 보정을 받고, 주문과 연계할 때는 선택한 무기로 한 번 공격합니다.", "Choose one type of light or one-handed melee weapon and gain proficiency with it. Wield a weapon of that type in either hand and a quarterstaff in the other to gain the accuracy bonus with both. Strike once with the chosen weapon when combining a spell and a strike.") },
            { "training.name", ("검과 지팡이", "Sword and Staff") },
            { "training.desc", ("선택한 무기와 쿼터스태프를 함께 들면 지팡이를 한 손에 들며, 두 무기의 근접 명중에 같은 레벨 전사와 아카니스트의 기본 공격 보너스 차이를 더합니다. 본인 주문으로 적을 맞히면 다음 선택 무기 명중에, 선택 무기로 맞히면 같은 적에 대한 다음 아카니스트 주문 명중에 +1을 받습니다. 내성 주문에는 그 적의 내성에 −1을 적용합니다. 보정은 아카니스트 7·13·19레벨에 각각 2·3·4로 커지며 다음 자기 턴 종료까지 한 번 적용됩니다(실시간 1라운드). 이 연계는 무료입니다. 두 행동을 묶으면 일반 검격에 저수지 1점을 쓰고 같은 보정을 받습니다.", "Wield a quarterstaff in one hand alongside your chosen weapon to add the difference between fighter and arcanist base attack bonuses to melee rolls with either. Landing an arcanist spell opens that enemy to your next chosen-weapon attack. A hit with your chosen weapon grants +1 on your next spell attack against that enemy or −1 to its next save against your arcanist spell. Both bonuses are 1 at level 1, 2 at 7, 3 at 13 and 4 at 19. Each applies once through the end of your next turn (one round in real time). Alternating actions is free. Spend 1 reservoir point for a regular combined strike in either order, with the same bonuses.") },
            { "first.name", ("검격 먼저", "Strike Before Casting") },
            { "first.desc", ("켠 뒤 주문을 평소처럼 선택합니다. 주문 효과가 발생하기 직전에 선택한 무기로 한 번 공격합니다. 지정한 적을 우선하고, 지정이 없으면 자동 검격과 같은 규칙으로 고릅니다. 일반 연계는 공격 시 저수지 1점을 쓰며 빗나가도 주문은 시전합니다. 검격이 맞으면 같은 적의 다음 주문 판정에 곧바로 보정이 붙습니다. 자동 안전 검격이나 수동 안전 지정을 함께 쓰면 기존 보호 비용을 적용합니다.", "Select a spell normally. Immediately before resolving it, strike once with your chosen weapon. Use your designated foe or automatic targeting. A regular strike costs 1 reservoir point and your spell proceeds on a miss. A hit immediately improves the next spell roll against the same foe. Guarded designations or automatic guarded casting use their listed protection cost.") },
            { "bladeOpening.name", ("검격의 빈틈", "Opening for the Blade") },
            { "bladeOpening.desc", ("이 적에게 주문을 적중시킨 그레이 시어는 다음 자기 턴이 끝나기 전 선택한 무기로 이 적을 공격할 때 한 번 명중에 +1/+2/+3/+4를 받습니다(아카니스트 1/7/13/19레벨).", "The grey seer who landed the spell gains +1/+2/+3/+4 on their next chosen-weapon attack against this enemy through the end of their next turn (arcanist levels 1/7/13/19).") },
            { "spellOpening.name", ("주문의 빈틈", "Opening for the Spell") },
            { "spellOpening.desc", ("이 적을 검격으로 맞힌 그레이 시어는 다음 자기 턴 종료까지 이 적에 대한 다음 아카니스트 주문 명중에 +1/+2/+3/+4를 받거나 이 적의 주문 내성에 같은 크기의 페널티를 줍니다. 한 번 적용됩니다.", "For the grey seer who landed the strike, the next arcanist spell attack against this enemy gains +1/+2/+3/+4, or the enemy takes an equal penalty on its save. Applies once through the end of the seer’s next turn.") },
            { "mark.name", ("검격 대상 지정", "Designate for Spell and Sword") },
            { "mark.desc", ("다음 아카니스트 주문 뒤 벨 적을 고릅니다. 주문은 자유롭게 겨냥할 수 있습니다. 시전이 성공하고 지정한 적이 선택한 무기의 사거리 안에 있으면 저수지 1점을 써서 추가 행동 없이 한 번 공격합니다. 다시 지정하면 이전 선택을 대체합니다.", "Choose a foe before casting your next arcanist spell. The spell may have any target. After a successful cast, spend 1 reservoir point to strike the designated foe once if within reach of your chosen weapon. Designating a foe again replaces the previous choice.") },
            { "safe.name", ("안전 검격 대상 지정", "Designate for Guarded Casting") },
            { "safe.desc", ("검격을 지정하고 방어적 시전이 필요할 때 자동 성공합니다. 슬롯 0~3단계는 1점, 4~6단계는 2점, 7~9단계는 3점을 먼저 지불하며 검격 비용을 포함합니다. 부족하면 일반 방어적 시전으로 돌아가고 검격은 취소됩니다. 보호 비용을 낸 뒤 주문이 끊기거나 적이 이탈해도 소비한 점수는 돌아오지 않습니다. 방어적 시전이 필요 없으면 검격에만 1점을 씁니다.", "Designate a foe and automatically succeed if the spell requires defensive casting. Pay a total of 1 point for slots 0–3, 2 for 4–6, or 3 for 7–9 at the defensive check. Insufficient points cancel the strike and leave the usual check in place. Interruptions or a lost target do not refund protection. Without a defensive check, only a successful follow-up costs 1 point.") },
            { "auto.name", ("자동 검격", "Automatic Spell and Sword") },
            { "auto.desc", ("본인 아카니스트 주문을 쓸 때 선택한 무기가 닿는 주문 대상을 우선합니다. 그럴 수 없으면 자신과 교전 중인 적 중 선택한 무기가 닿는 가장 가까운 적을 고릅니다. 시전 후 그 적을 공격할 때 저수지 1점을 씁니다. 직접 지정하면 그 주문 한 번에 우선합니다. 켜면 자동 안전 검격이 꺼집니다.", "When you cast your own arcanist spell, choose its enemy target if within reach of your chosen weapon. Otherwise choose the nearest visible opponent engaged with you and within reach. Spend 1 reservoir point when making the follow-up attack. A manual designation overrides this mode for one spell. Enabling this turns off Automatic Guarded Casting.") },
            { "autoSafe.name", ("자동 안전 검격", "Automatic Guarded Casting") },
            { "autoSafe.desc", ("자동 검격과 같은 규칙으로 적을 고릅니다. 적을 골랐고 방어적 시전이 필요하면 저수지 1점(슬롯 0~3단계), 2점(4~6단계), 3점(7~9단계)을 먼저 써서 자동 성공합니다. 검격 비용을 포함하며 보호를 받으면 돌려받지 못합니다. 점수가 부족하면 일반 판정만 합니다. 방어적 시전이 필요 없으면 검격에 1점만 씁니다. 수동 지정은 한 번 우선하며, 켜면 자동 검격이 꺼집니다.", "Select a foe as for Automatic Spell and Sword. With a foe selected, pay 1 point for slots 0–3, 2 for 4–6, or 3 for 7–9 to pass a required defensive casting check. This includes the strike and is spent even if the strike is lost. Insufficient points leave the normal check and cancel the strike. Without a check, only the strike costs 1 point. A manual designation takes priority for one spell. Enabling this turns off Automatic Spell and Sword.") },
            { "equipment", ("선택한 무기와 쿼터스태프를 함께 장착해야 합니다.", "Wield your chosen weapon and a quarterstaff together.") }
        };
    }
}
